files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e8e8e8;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #0f3460;
}

h1 {
  font-size: 24px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #e94560;
  margin-bottom: 16px;
  text-align: center;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 16px;
  background: #0f3460;
  border: 3px solid #1a1a2e;
  color: #e8e8e8;
  outline: none;
}

input[type="text"]:focus {
  border-color: #e94560;
}

button {
  font-size: 16px;
  padding: 10px 18px;
  background: #e94560;
  color: #fff;
  border: 3px solid #1a1a2e;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
}

button:hover {
  background: #ff5c77;
}

button:active {
  transform: translate(2px, 2px);
}

button:focus-visible {
  outline: 3px solid #e8e8e8;
  outline-offset: 2px;
}

.counts {
  display: flex;
  gap: 24px;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 16px;
}

.counts strong {
  color: #e94560;
}

#todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

#todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #0f3460;
  padding: 10px 12px;
  border: 3px solid #1a1a2e;
}

#todo-list li.done span {
  text-decoration: line-through;
  opacity: 0.6;
}

#todo-list span {
  flex: 1;
  word-break: break-word;
}

#todo-list input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
}

.delete-btn {
  padding: 4px 10px;
  font-size: 14px;
  background: #1a1a2e;
  border-color: #e94560;
  color: #e94560;
}

.delete-btn:hover {
  background: #e94560;
  color: #fff;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 #0f3460;
  }
  h1 {
    font-size: 20px;
  }
}

let nextId = 1;
let total = 0;
let remaining = 0;

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = total;
  remainingEl.textContent = remaining;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const id = nextId++;
  total++;
  remaining++;
  updateCounts();

  const li = document.createElement('li');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + id;
  checkbox.setAttribute('aria-label', 'Mark task ' + id + ' as done');
  checkbox.addEventListener('change', () => {
    if (checkbox.checked) {
      remaining--;
      li.classList.add('done');
    } else {
      remaining++;
      li.classList.remove('done');
    }
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = 'todo-text-' + id;
  span.textContent = text;

  const delBtn = document.createElement('button');
  delBtn.id = 'todo-delete-' + id;
  delBtn.className = 'delete-btn';
  delBtn.type = 'button';
  delBtn.textContent = 'X';
  delBtn.setAttribute('aria-label', 'Delete task ' + id);
  delBtn.addEventListener('click', () => {
    if (!checkbox.checked) remaining--;
    total--;
    updateCounts();
    li.remove();
  });

  li.append(checkbox, span, delBtn);
  list.appendChild(li);
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', (e) => {
  e.preventDefault();
  addTask();
});

input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask();
  }
});

updateCounts();
